// LEDC makes the PWM: attach it to the pin, then write a duty
const int LED_PIN = 23;
const int FREQ_HZ = {{p:freq}};
const int RESOLUTION = {{p:bits}};

void setup() {
  Serial.begin(115200);
  ledcAttach(LED_PIN, FREQ_HZ, RESOLUTION);
  Serial.println("LEDC fade on GPIO23");
}

void loop() {
  int maxDuty = (1 << RESOLUTION) - 1;
  for (int i = 0; i <= 50; i++) {
    ledcWrite(LED_PIN, maxDuty * i / 50);
    delay(20);
  }
  for (int i = 50; i >= 0; i--) {
    ledcWrite(LED_PIN, maxDuty * i / 50);
    delay(20);
  }
}

